def test_stage4_second_reading_matches_legacy(realistic_results, legacy):
    _assert_subset_matches(
        legacy["out-rr-robust"]["second_reading"],
        realistic_results["stage4_robust"]["second_reading"],
        where="second_reading",
    )


def test_stage4_walls_matches_legacy(realistic_results, legacy):
    _assert_subset_matches(
        legacy["out-rr-robust"]["walls"], realistic_results["stage4_robust"]["walls"],
        where="walls",
    )


def test_stage4_tmin_matches_legacy(realistic_results, legacy):
    old = legacy["out-rr-robust"]["tmin"]
    new = realistic_results["stage4_robust"]["tmin"]
    for key in ("osmium-paul", "torsion-mg", "levitated-gs"):
        _assert_subset_matches(old[key], new[key], where=f"tmin.{key}")
    _assert_subset_matches(
        old["Y25 torsion balance"], new["Y25_torsion_balance"], where="tmin.Y25"
    )


# -------------------------------- stage 1 and 0: no legacy json (text-only originally),
# pinned here from the legacy scripts' own printed output instead.
def test_stage1_baseline_matches_the_original_run(realistic_results):
    b = realistic_results["stage1_platforms"]["baseline"]["osmium-paul"]
    # rr-platforms.py's own stdout, this repository's prior run:
    #   nbar = 2.0837e+08  purity = 2.2562e-09  eta_eff = 0.000000  f = 0.000000
    #   V_unc = 2.2400e-16  V_all = 4.8937e-25  split = 4.2016e-03  G_theory = 3.2402e+01
    assert b["nbar"] == pytest.approx(2.0837e08, rel=1e-4)
    assert b["V_unc"] == pytest.approx(2.2400e-16, rel=1e-4)
    assert b["V_all"] == pytest.approx(4.8937e-25, rel=1e-4)
    assert b["split_theory"] == pytest.approx(4.2016e-03, rel=1e-4)
    assert b["G_theory"] == pytest.approx(3.2402e01, rel=1e-4)


def test_stage0_filter_reproduces_its_two_limits(realistic_results):
    fc = realistic_results["stage0_adapter"]["filter_check"]
    assert fc["V_unconditional"] == pytest.approx(fc["equipartition"], rel=1e-9)
    assert fc["V_conditioned"] == pytest.approx(fc["ground_state"], rel=1e-3)
    assert fc["purity_filter"] == pytest.approx(fc["purity_formula"], rel=1e-9)


def test_stage0_adapter_reduces_to_the_law_exactly(realistic_results):
    assert realistic_results["stage0_adapter"]["eta_eff_check"]["worst"] < 1e-12
    assert realistic_results["stage0_adapter"]["f_reduction_check"]["worst"] < 1e-12
